output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "shelfCanyon": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfCanyon"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not enter a single-file aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "shelfCanyon": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfCanyon"
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": "MOVE",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever an agent parks or releases a cart, they are obliged to retrieve a cart before finishing.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "putDownCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "park_only_at_aisle_mouth",
    "text": "Carts may only be parked at designated wide aisle-mouth cells before entering cart-free aisles.",
    "abstraction": {
      "state_properties": {
        "wideUpperCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "designatedAisleMouth": {
          "and": [
            "wideUpperCrossAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "putDownCart",
          {
            "not": "designatedAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_movement_only_near_restricted_aisles",
    "text": "Except for the initial approach to the cart station, moving without a cart is allowed only inside a single-file aisle or from its aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartStationApproach": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessMoveOrigin": {
          "or": [
            "singleFileAisle",
            "aisleMouth",
            "cartStationApproach"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessMoveOrigin"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_service_requires_cart",
    "text": "Interacting with an open-aisle shelf requires having a cart, while shelf interactions inside single-file aisles may be done without one.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "openAisleShelf": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openAisleShelf",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_items_hand_carried",
    "text": "Items taken from single-file shelf aisles must be collected by hand rather than while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "eastbound_main_aisle_traffic",
    "text": "Main horizontal aisles are one-way eastbound, so westward travel in them is prohibited.",
    "abstraction": {
      "state_properties": {
        "mainHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "mainHorizontalAisle"
        ]
      }
    }
  }
]
